<div class="page-actions"><?php if ($user['role']==='donor'): ?><a class="button" href="/donations/new">Share surplus food ↗</a><?php elseif ($user['role']==='receiver'): ?><a class="button" href="/receiving">Set capacity & availability</a><?php endif ?></div>
<?php if (!$data['donations']): ?><p class="empty-state">No donations to display yet. Listings will appear here when food is offered.</p><?php else: ?>
<div class="donation-grid"><?php foreach ($data['donations'] as $food): ?><article class="panel donation-card"><div class="card-top"><?php badge($food['status']); ?><span><?= e($food['category_name']) ?></span></div><h2><a href="/donations/<?= e($food['id']) ?>"><?= e($food['name']) ?></a></h2><p><?= e($food['organization_name']) ?></p><strong class="quantity"><?= e($food['quantity_kg']) ?> <small><?= $food['status']==='available' ? 'kg available' : 'kg offered' ?></small></strong><p class="muted">Pickup by <?php stamp($food['deadline']); ?></p>
<?php if ($user['role']==='receiver'): $match=$data['recommendations'][$food['id']] ?? null; ?><p><?= $match ? 'TAMRA score: ' . e(number_format($match['score']*100,1)) . '/100 · ' . e($match['distance_km']) . ' km' : 'No eligible match for your current preferences.' ?></p><?php endif ?>
<a class="underlined" href="/donations/<?= e($food['id']) ?>">View food and collection details →</a></article><?php endforeach ?></div><?php endif ?>
